/* Estações do treino. Para exibir as fotos, coloque os arquivos na pasta img/ e troque false por true na linha abaixo. */
window.OSCE_IMAGENS = false;
window.OSCE_STATIONS = [{"id":"A1","sim":"A","origem":"Elaborado para treino","titulo":"Estação A1","tema":"meningite","corpo":[{"t":"p","h":"<strong>Caso.</strong> Homem, 24 anos, trazido pela mãe com febre, dor de cabeça forte e vômitos há 2 dias. Hoje está sonolento."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie o nível de consciência pela escala de coma de Glasgow e informe a pontuação.","Realize e descreva a pesquisa de rigidez de nuca, a prova de Brudzinski e a prova de Kernig.","Qual a síndrome e qual o mecanismo de lesão mais provável?"]}],"instrucao":"Fique de olhos fechados e abra só quando chamarem. Diga seu nome certo, mas erre o dia e o lugar. Obedeça às ordens. Resista quando dobrarem o seu pescoço. Dobre os joelhos quando forçarem a cabeça para a frente. Reclame de dor atrás da coxa e resista quando esticarem o joelho.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Glasgow: avaliou os três parâmetros na ordem (observa, chama, pergunta, dá ordem; dor só se necessário)","pts":1.5},{"item":"Informou os componentes e o total: ocular 3 (ao chamado), verbal 4 (confusa), motora 6 = 13","pts":1.5},{"item":"Rigidez de nuca: decúbito dorsal, mão no occipício, flexão suave; descreveu a resistência","pts":1.5},{"item":"Brudzinski: mão sobre o tórax, flexão forçada da cabeça, observou os membros inferiores; descreveu a flexão dos joelhos","pts":1.5},{"item":"Kernig: coxa e perna a 90°, extensão da perna, dos dois lados; descreveu dor e resistência","pts":1.5},{"item":"Síndrome meníngea","pts":0.5},{"item":"Mecanismo infeccioso (meningite), justificado por febre e instalação em dias","pts":1.0}],"notas":[]},{"id":"A2","sim":"A","origem":"Elaborado para treino","titulo":"Estação A2","tema":"hipertireoidismo","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 32 anos, emagreceu 6 kg em 2 meses apesar de comer bem. Queixa-se de palpitações, tremor nas mãos e calor excessivo."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize e descreva a palpação da tireoide pela abordagem anterior.","Realize e descreva a palpação dos linfonodos cervicais anteriores e posteriores.","Figura: rosto de frente; nos dois olhos a esclera aparece acima e abaixo da íris; olhar de espanto, olhos brilhantes. Nomeie o achado e a fácies.","Qual o mecanismo de lesão da alteração ocular?"]}],"instrucao":"Exame normal. Engula quando pedirem.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção do pescoço, com deglutição","pts":1.0},{"item":"Abordagem anterior correta: de frente, polegares sobre a glândula, demais dedos nas regiões supraclaviculares","pts":1.5},{"item":"Palpou istmo e os dois lobos, pedindo deglutição","pts":1.0},{"item":"Descreveu pelo menos cinco características (volume, consistência, superfície, limites, mobilidade, sensibilidade, nódulos, frêmito)","pts":1.5},{"item":"Linfonodos: polpas digitais, movimentos circulares, cadeias anterior e posterior, dos dois lados","pts":1.5},{"item":"Descreveu tamanho, consistência, mobilidade, sensibilidade, coalescência e pele","pts":1.0},{"item":"Exoftalmia bilateral e fácies basedowiana","pts":1.0},{"item":"Mecanismo autoimune (inflamatório): anticorpos contra o tecido retro-orbitário","pts":0.5}],"notas":["Na paciente real com doença de Graves o esperado seria bócio difuso, liso, elástico, indolor e móvel, às vezes com frêmito e sopro."]},{"id":"A3","sim":"A","origem":"Elaborado para treino","titulo":"Estação A3","tema":"lombociatalgia","corpo":[{"t":"p","h":"<strong>Caso.</strong> Homem, 45 anos, pedreiro. Dor lombar há 3 semanas, iniciada ao levantar um saco de cimento. A dor desce pela nádega, pela face posterior da coxa e da perna direitas até a borda lateral do pé, e piora ao tossir."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie a coluna lombar.","Avalie os reflexos profundos dos membros inferiores e diga qual você espera encontrar alterado.","Realize e descreva a manobra de Lasègue.","Classifique a evolução temporal da dor e diga qual raiz está provavelmente acometida."]}],"instrucao":"Incline-se pouco para a frente, com dor. Reclame de dor à palpação lombar baixa à direita. No Lasègue à direita, reclame de dor que desce por trás da coxa e da perna quando o membro chegar a uns 40°. À esquerda, nada.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção estática por trás e de perfil (simetria, curvaturas, pele, atitude antálgica)","pts":1.0},{"item":"Inspeção dinâmica: flexão, extensão, inclinações laterais e rotação","pts":1.0},{"item":"Palpação de apófises espinhosas e musculatura paravertebral","pts":1.0},{"item":"Reflexos patelar e aquileu, com técnica correta, dos dois lados, graduados","pts":1.5},{"item":"Espera aquileu diminuído à direita","pts":1.0},{"item":"Lasègue: decúbito dorsal, elevação do membro com o joelho estendido, dos dois lados","pts":1.5},{"item":"Descreveu o ângulo e o trajeto da dor; citou Bragard ou diferenciou de dor muscular","pts":1.0},{"item":"Evolução aguda (menos de 6 semanas)","pts":0.5},{"item":"Raiz S1 (dor até a borda lateral do pé, reflexo aquileu)","pts":0.5}],"notas":["Bônus: teste de Schober; andar na ponta dos pés (S1) e nos calcanhares (L5). A causa provável é hérnia discal entre L5 e S1, mecanismo compressivo."]},{"id":"A4","sim":"A","origem":"Elaborado para treino","titulo":"Estação A4","tema":"tumor selar","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 38 anos, com dor de cabeça há 6 meses. Conta que esbarra nos batentes das portas e não percebe os carros que vêm pelos lados."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Teste a acuidade visual.","Avalie os nervos cranianos III, IV e VI.","Quais músculos são inervados pelo IV e pelo VI?","Qual achado do exame visual você espera na lesão do quiasma óptico, e por quê?"]}],"instrucao":"Leia a tabela normalmente com cada olho. Acompanhe o dedo com os olhos, sem mexer a cabeça.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Acuidade: um olho de cada vez, com óculos se usar, oclusão sem pressão, tabela de Snellen a 6 metros (ou leitura), registrou o resultado de cada olho","pts":2.0},{"item":"Inspeção: ptose, estrabismo, posição dos olhos","pts":0.5},{"item":"Motilidade extrínseca em H, cabeça parada; perguntou por visão dupla","pts":1.5},{"item":"Convergência","pts":0.5},{"item":"Pupilas: forma e tamanho; reflexo fotomotor direto e consensual","pts":1.0},{"item":"IV: oblíquo superior","pts":1.0},{"item":"VI: reto lateral","pts":1.0},{"item":"Hemianopsia heterônima bitemporal, porque no quiasma cruzam as fibras das retinas nasais","pts":1.5}],"notas":["Bônus: campo visual por confrontação; mecanismo neoplásico (tumor da região selar, pela evolução lenta)."]},{"id":"A5","sim":"A","origem":"Elaborado para treino","titulo":"Estação A5","tema":"polineuropatia diabética","corpo":[{"t":"p","h":"<strong>Caso.</strong> Homem, 60 anos, diabético há 20 anos. Há 1 ano tem formigamento e dormência nos dois pés, agora também nas mãos. Sente-se inseguro para andar no escuro."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie a sensibilidade superficial e profunda nos membros superiores e inferiores.","Avalie a coordenação motora dos membros inferiores.","Qual padrão de distribuição você espera e como se chamam os achados?","Qual prova de equilíbrio estático você espera alterada, e por quê?"]}],"instrucao":"De olhos fechados, diga que não sente o algodão nem a vibração nos pés e sente pouco até o meio das pernas; nas mãos, sente menos até os punhos. Erre a posição do hálux. No calcanhar-joelho, faça certo de olhos abertos e erre de olhos fechados.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Explicou e demonstrou o estímulo antes; mandou fechar os olhos; não sugeriu a resposta","pts":1.0},{"item":"Superficial: tátil com algodão (e dolorosa com estilete rombo, ou citou); nomeou o instrumento","pts":1.5},{"item":"Profunda: vibratória com diapasão de 128 Hz em saliências ósseas e cinético-postural no hálux e no polegar","pts":1.5},{"item":"De distal para proximal, comparando os lados, nos quatro membros","pts":1.0},{"item":"Coordenação: calcanhar-joelho de olhos abertos e fechados, dos dois lados, e movimentos alternados dos pés","pts":1.5},{"item":"Padrão em bota e luva (distal e simétrico); hipoestesia tátil, hipopalestesia, alteração da cinético-postural","pts":1.5},{"item":"Romberg positivo, por perda da propriocepção: o paciente depende da visão para se equilibrar","pts":1.0}],"notas":["Neste caso a incoordenação que aparece só de olhos fechados é ataxia sensitiva, não cerebelar."]},{"id":"B1","sim":"B","origem":"Elaborado para treino","titulo":"Estação B1","tema":"sequela de AVC","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 68 anos, hipertensa. Há 6 meses perdeu de repente a força do lado direito do corpo. Hoje anda arrastando a perna direita."},{"t":"p","h":"Figura: ao sorrir, a boca desvia para a esquerda e o sulco nasolabial direito está apagado. Ela enruga a testa dos dois lados e fecha bem os dois olhos."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Teste o tônus do membro superior direito e descreva o achado.","Teste os reflexos bicipital e patelar e descreva os achados.","Pesquise o reflexo cutâneo-plantar e diga o achado esperado.","A paralisia facial da figura é central ou periférica? Justifique.","Qual neurônio motor está acometido e qual o mecanismo de lesão?"]}],"instrucao":"Mantenha o braço direito dobrado junto ao corpo. Quando mexerem o seu cotovelo direito, resista no começo e solte de repente. O lado esquerdo é normal.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Tônus: movimentos passivos de cotovelo e punho, comparando com o outro lado","pts":1.0},{"item":"Hipertonia elástica (espasticidade), sinal do canivete","pts":1.0},{"item":"Reflexos bicipital e patelar com técnica correta, dos dois lados","pts":1.0},{"item":"Hiper-reflexia à direita (3+ ou 4+ em 4+) e reflexos normais à esquerda","pts":1.0},{"item":"Cutâneo-plantar: estímulo pela borda lateral da planta, do calcanhar para os dedos","pts":0.5},{"item":"Sinal de Babinski à direita (extensão do hálux)","pts":1.0},{"item":"Paralisia facial central: só a metade inferior da face, testa e fechamento dos olhos preservados","pts":1.5},{"item":"A lesão está no hemisfério esquerdo (face e corpo direitos)","pts":0.5},{"item":"Primeiro neurônio motor","pts":0.5},{"item":"Mecanismo vascular (início súbito)","pts":1.0}],"notas":[]},{"id":"B2","sim":"B","origem":"Elaborado para treino","titulo":"Estação B2","tema":"Parkinson","corpo":[{"t":"p","h":"<strong>Caso.</strong> Homem, 70 anos. Há 2 anos tem tremor na mão direita, que melhora quando pega objetos. Está mais lento para se vestir e a letra ficou pequena."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Diga o que você procura na inspeção (fácies, atitude, movimentos involuntários).","Teste o tônus dos membros superiores e nomeie o achado esperado.","Avalie a marcha e descreva o que espera ver.","Avalie a coordenação do membro superior e o equilíbrio estático.","Qual o mecanismo de lesão?"]}],"instrucao":"Pouca expressão no rosto. Tremor na mão direita em repouso, que para quando você pega algo. Quando mexerem o seu braço, resista o tempo todo, em pequenos trancos. Ande com passos curtos, tronco inclinado, sem balançar os braços.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção: fácies parkinsoniana (pouca mímica), atitude em flexão, tremor de repouso","pts":1.5},{"item":"Tônus por movimentos passivos, dos dois lados","pts":1.0},{"item":"Hipertonia plástica (rigidez), sinal da roda denteada","pts":1.0},{"item":"Marcha: ofereceu apoio; descreveu marcha em bloco, passos curtos e rápidos, sem balanço dos braços","pts":2.0},{"item":"Índex-nariz dos dois lados, de olhos abertos e fechados; descreveu o achado","pts":1.0},{"item":"Romberg com apoio oferecido; descreveu o resultado","pts":1.0},{"item":"Mecanismo degenerativo","pts":1.0},{"item":"Reconheceu a letra pequena (micrografia) como bradicinesia","pts":0.5}],"notas":["Na doença de Parkinson clássica a coordenação é normal, apenas lenta. No OSCE da T104, o paciente simulado errava o nariz e caía no Romberg, e o gabarito pedia &quot;dismetria&quot; e &quot;Romberg positivo&quot;. Descreva o que o paciente fizer, não o que o livro prevê."]},{"id":"B3","sim":"B","origem":"Elaborado para treino","titulo":"Estação B3","tema":"síndrome cerebelar","corpo":[{"t":"p","h":"<strong>Caso.</strong> Homem, 52 anos, etilismo pesado há 25 anos. Anda cambaleando, com as pernas afastadas, mesmo sem ter bebido. A fala está &quot;enrolada&quot; e ele derruba copos."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie a coordenação dos membros superiores com duas provas e nomeie os achados esperados.","Realize a prova de Romberg e diga o resultado esperado.","Cite três outros achados dessa síndrome.","Como você diferencia esse quadro de uma ataxia por perda da propriocepção?"]}],"instrucao":"Erre o nariz e trema ao chegar perto dele, igual de olhos abertos e fechados. Faça os movimentos alternados de forma desajeitada. De pé, afaste as pernas e balance já de olhos abertos, sem piorar ao fechá-los.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Índex-nariz: braço estendido lateralmente, olhos abertos e fechados, dos dois lados","pts":1.0},{"item":"Dismetria e tremor de ação (intencional)","pts":1.0},{"item":"Movimentos alternados (pronação e supinação): disdiadococinesia","pts":1.0},{"item":"Romberg com técnica correta e apoio oferecido","pts":1.0},{"item":"Romberg negativo: o desequilíbrio existe de olhos abertos e não piora ao fechá-los","pts":1.0},{"item":"Três achados entre: marcha do ébrio com base alargada, fala escandida, hipotonia, reflexos pendulares, nistagmo, macrografia, assinergia","pts":2.0},{"item":"Diferenciação: na ataxia sensitiva a incoordenação piora de olhos fechados, o Romberg é positivo e as sensibilidades vibratória e cinético-postural estão alteradas","pts":2.0}],"notas":[]},{"id":"B4","sim":"B","origem":"Elaborado para treino","titulo":"Estação B4","tema":"paralisia facial periférica","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 28 anos, acordou com o rosto &quot;torto&quot;. Não tem fraqueza em braços ou pernas."},{"t":"p","h":"Figura: não enruga a testa à esquerda; o olho esquerdo não fecha; ao mostrar os dentes, a boca desvia para a direita."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Examine o nervo facial.","A paralisia é central ou periférica? De que lado é a lesão? Justifique.","Como se chama o achado do olho que não fecha, e que risco ele traz?","No reflexo córneo-palpebral, qual nervo é a via aferente e qual é a eferente?"]}],"instrucao":"Não mexa o lado esquerdo do rosto.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Pediu: enrugar a testa, franzir os supercílios, fechar os olhos com força, mostrar os dentes, assobiar, inflar as bochechas, contrair o platisma (pelo menos cinco)","pts":3.0},{"item":"Paralisia periférica, porque acomete toda a hemiface, incluindo testa e olho","pts":1.5},{"item":"Lesão à esquerda (mesmo lado da face paralisada); a boca desvia para o lado normal","pts":1.0},{"item":"Lagoftalmia; risco de ressecamento e úlcera de córnea","pts":1.5},{"item":"Reflexo córneo-palpebral: aferente V (ramo oftálmico), eferente VII","pts":2.0}],"notas":["Causa mais comum: paralisia a frigore (de Bell), cerca de 80% dos casos segundo o Porto."]},{"id":"B5","sim":"B","origem":"Elaborado para treino","titulo":"Estação B5","tema":"psoríase e petéquias","corpo":[{"t":"p","h":"<strong>Caso.</strong> Duas figuras de pele."},{"t":"p","h":"Figura 1: cotovelos e joelhos com áreas elevadas em platô, maiores que 2 cm, vermelhas, de bordas nítidas, cobertas por escamas esbranquiçadas e prateadas, dos dois lados."},{"t":"p","h":"Figura 2: pernas com muitos pontos vermelho-arroxeados de 1 a 3 mm, planos, que não desaparecem quando se comprime com uma lâmina de vidro."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Descreva as lesões da figura 1.","Cite dois sinais semiológicos da doença mais provável e o mecanismo de lesão.","Nomeie a lesão da figura 2 e explique como diferenciá-la de um eritema.","Como se chamaria a lesão da figura 2 se fosse uma placa maior que 1 cm? E se fosse linear?"]}],"instrucao":"","checklist":[{"item":"Figura 1: placas eritematosas","pts":1.0},{"item":"Bem delimitadas, descamativas, com escamas prateadas","pts":1.0},{"item":"Distribuição simétrica em cotovelos e joelhos (faces extensoras)","pts":1.0},{"item":"Sinal da vela e sinal de Auspitz","pts":1.5},{"item":"Mecanismo inflamatório; psoríase","pts":1.5},{"item":"Figura 2: petéquias (púrpura)","pts":1.0},{"item":"Não desaparecem à digitopressão ou vitropressão, porque são sangue extravasado; o eritema desaparece, porque é vasodilatação","pts":1.5},{"item":"Placa maior que 1 cm: equimose. Linear: víbice","pts":1.5}],"notas":[]},{"id":"B6","sim":"B","origem":"Elaborado para treino","titulo":"Estação B6","tema":"osteoartrite","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 62 anos, com dor nos joelhos e nas mãos há 3 anos. A dor piora no fim do dia e ao subir escadas e melhora com o repouso. A rigidez ao acordar dura cerca de 10 minutos. Nas mãos há nódulos duros e indolores nas articulações interfalângicas distais e proximais."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Classifique a evolução e o padrão da dor, justificando.","Nomeie os nódulos das mãos.","Examine o joelho: inspeção, pesquisa de derrame articular e um teste de menisco.","Qual o mecanismo de lesão e a doença mais provável?"]}],"instrucao":"Exame do joelho normal, com leve dor na parte de dentro do joelho no teste de menisco.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Evolução crônica (mais de 6 semanas)","pts":0.5},{"item":"Dor mecânica: rigidez matinal menor que 30 minutos, piora com o uso e no fim do dia, melhora com o repouso","pts":1.5},{"item":"Nódulos de Heberden (distais) e de Bouchard (proximais)","pts":2.0},{"item":"Joelho: inspeção (alinhamento em valgo ou varo, volume) e palpação da temperatura","pts":1.0},{"item":"Sinal da tecla: esvaziou a bolsa suprapatelar e comprimiu a patela","pts":1.0},{"item":"McMurray ou Apley com técnica e interpretação corretas (rotação externa testa o menisco medial; rotação interna, o lateral)","pts":2.0},{"item":"Mecanismo degenerativo; osteoartrite","pts":1.0}],"notas":[]},{"id":"C-05","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 05","tema":"","corpo":[{"t":"p","h":"<strong>Cenário.</strong> Paciente do sexo masculino, 25 anos, com queixa de febre e cefaleia de forte intensidade em toda a cabeça, se apresenta no pronto atendimento para consulta."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie o nível de consciência do paciente pela escala de Glasgow.","Realize e descreva a avaliação da rigidez de nuca.","Realize e descreva a prova de Brudzinski.","Realize e descreva a prova de Kernig."]}],"instrucao":"Acordado e colaborativo; responda certo a nome, lugar e data. Exame normal, a menos que combinem o contrário.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Glasgow: abertura ocular, resposta verbal (nome, lugar, data) e resposta motora (ordem simples), na ordem; dor só se necessário","pts":2.0},{"item":"Disse os três componentes e o total (4 + 5 + 6 = 15)","pts":1.0},{"item":"Rigidez de nuca: decúbito dorsal sem travesseiro, mão no occipício, flexão suave; \"nuca livre\" ou \"resistência à flexão\"","pts":2.0},{"item":"Brudzinski: mão sobre o tórax, flexão forçada da cabeça, olhando os joelhos; positivo = flexão dos membros inferiores","pts":2.0},{"item":"Kernig: coxa a 90° sobre a bacia e perna a 90° sobre a coxa, estender a perna, dos dois lados; positivo = dor no trajeto do ciático e resistência","pts":2.0}],"notas":["Se o avaliador perguntar: febre com cefaleia e sinais meníngeos compõe a síndrome meníngea; mecanismo infeccioso (meningite)."]},{"id":"C-06","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 06","tema":"","corpo":[{"t":"p","h":"<strong>Cenário (escrito para treino).</strong> Mulher, 30 anos, com palpitações, perda de peso e aumento de volume na região anterior do pescoço."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize e descreva a palpação de tireoide pela abordagem anterior.","Realize e descreva a palpação de linfonodos na região cervical anterior.","Realize e descreva a palpação de linfonodos na região cervical posterior.","Qual o achado da figura da questão? (Figura: olhos salientes, com esclera visível acima e abaixo da íris.)"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção do pescoço com deglutição","pts":0.5},{"item":"Abordagem anterior: de frente, polegares sobre a glândula, demais dedos nas regiões supraclaviculares; istmo e os dois lobos, com deglutição","pts":2.0},{"item":"Descreveu volume, consistência, superfície, limites, mobilidade, sensibilidade e nódulos","pts":1.5},{"item":"Linfonodos cervicais anteriores: polpas digitais, movimentos circulares, cabeça inclinada para o lado examinado, dos dois lados","pts":1.5},{"item":"Linfonodos cervicais posteriores, do mesmo modo","pts":1.5},{"item":"Descreveu tamanho, consistência, mobilidade, sensibilidade, coalescência e pele","pts":1.0},{"item":"Figura: exoftalmia; sugere hipertireoidismo (doença de Graves)","pts":1.0}],"notas":[],"img":"img/c_06.jpg"},{"id":"C-07","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 07","tema":"","corpo":[{"t":"p","h":"<strong>Cenário.</strong> Jovem referindo lombalgia constante, de forte intensidade e com irradiação para a região posterior dos membros inferiores. Tais episódios álgicos o fazem procurar serviço de emergência para analgésicos parenterais de alívio."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie a coluna lombar desse paciente.","Realize ao menos 1 reflexo profundo de membros inferiores.","Realize e descreva a manobra de Lasègue."]}],"instrucao":"Dor ao inclinar o tronco para a frente. No Lasègue, dor lombar que desce por trás da coxa e passa do joelho quando a perna chega a uns 45°, dos dois lados.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção estática: pele, curvaturas (lordose lombar), simetria, deformidades","pts":1.0},{"item":"Inspeção dinâmica: flexão, extensão e inclinação lateral","pts":1.0},{"item":"Palpação de apófises espinhosas e musculatura paravertebral","pts":1.0},{"item":"Schober: marca nas espinhas ilíacas posterossuperiores e 10 cm acima; flexão máxima; normal = aumento de 5 cm","pts":1.0},{"item":"1 reflexo profundo de membro inferior (patelar ou aquileu) com técnica correta, dos dois lados, graduado","pts":2.0},{"item":"Lasègue: decúbito dorsal, elevação passiva do membro com o joelho estendido, dos dois lados","pts":1.5},{"item":"Descreveu: positivo se reproduz a dor lombar irradiada além do joelho entre 30° e 70°; disse o ângulo encontrado","pts":1.5}],"notas":["Bônus: testar L4 (dorsiflexão do tornozelo), L5 (extensão do hálux, andar nos calcanhares) e S1 (andar na ponta dos pés)."]},{"id":"C-09","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 09","tema":"","corpo":[{"t":"p","h":"<strong>Cenário (escrito para treino).</strong> Mulher, 48 anos, digitadora, com formigamento e dormência nas duas mãos há 4 meses, piores à noite. Diz que anda &quot;desequilibrada&quot;."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie 1 modalidade de sensibilidade profunda em membros superiores, na região referida no caso clínico.","Avalie 1 modalidade de sensibilidade superficial em membros superiores, na região referida no caso clínico.","Avalie a coordenação motora de membros inferiores."]}],"instrucao":"De olhos fechados, diga que sente menos o algodão na palma e nos três primeiros dedos das duas mãos. Vibração e posição do polegar normais. Calcanhar-joelho normal.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Identificou a região do caso (mãos) e examinou ali, dos dois lados","pts":1.0},{"item":"Explicou e mostrou o estímulo antes; mandou fechar os olhos; não sugeriu a resposta","pts":1.5},{"item":"1 modalidade profunda: vibratória (diapasão de 128 Hz no estiloide do rádio ou em falange) ou cinético-postural (polegar); nomeou a modalidade e o instrumento","pts":2.0},{"item":"1 modalidade superficial: tátil (algodão) ou dolorosa (estilete rombo); nomeou a modalidade e o instrumento","pts":2.0},{"item":"Relatou o achado com o termo certo (hipoestesia tátil; palestesia preservada)","pts":1.0},{"item":"Coordenação dos membros inferiores: calcanhar-joelho de olhos abertos e fechados, dos dois lados; relatou","pts":1.5}],"notas":[]},{"id":"C-11","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 11","tema":"","corpo":[{"t":"p","h":"<strong>Cenário.</strong> Você (aluno do segundo período de medicina) está avaliando paciente do pronto atendimento que relata dor de garganta associada a disfagia para líquidos e o aparecimento de ondulações cervicais há 1 semana."},{"t":"p","h":"<strong>Tarefas.</strong> Não é necessário escrever; realize e descreva em voz alta para o avaliador."},{"t":"ol","i":["Avalie os parâmetros do estado de hidratação do paciente.","Faça a palpação da cadeia de linfonodos submandibular e submentoniana.","Avalie o(s) par(es) craniano(s) relacionado(s) à alteração de disfagia."]}],"instrucao":"Exame normal. Diga que dói um pouco quando palparem abaixo da mandíbula.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Hidratação, pele: umidade, elasticidade e turgor (prega cutânea)","pts":1.0},{"item":"Hidratação, mucosas: umidade da conjuntiva e da mucosa oral","pts":1.0},{"item":"Hidratação: olhos (enoftalmia), estado geral, perda abrupta de peso; concluiu \"hidratado\" ou \"desidratado\"","pts":1.0},{"item":"Submentoniana: polpas digitais atrás do mento","pts":1.0},{"item":"Submandibular: ao longo da borda inferior da mandíbula, tecidos contra a base da mandíbula, dos dois lados","pts":1.0},{"item":"Descreveu tamanho, consistência, mobilidade, sensibilidade, coalescência e pele","pts":1.0},{"item":"Nomeou os pares IX e X (bônus: XII)","pts":1.0},{"item":"Examinou: \"aaa\" com elevação do palato e posição da úvula; reflexo do vômito; voz e deglutição","pts":1.5},{"item":"Relatou o achado","pts":0.5}],"notas":[]},{"id":"C-12","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 12","tema":"","corpo":[{"t":"p","h":"<strong>Cenário.</strong> Você (aluno do segundo período de medicina) está realizando a entrevista médica na enfermaria de clínica médica do HC-UFU. O(a) paciente refere adinamia, astenia e dificuldade para fazer suas atividades diárias nos últimos 3 meses. Também refere &quot;inchaço&quot; nos membros inferiores, que ocorre de maneira episódica. No questionamento dirigido sobre o aparelho digestivo, refere fezes com coloração de &quot;borra de café&quot;. Na história medicamentosa, refere usar muito anti-inflamatório."},{"t":"p","h":"<strong>Tarefas.</strong> Realize e descreva em voz alta para o avaliador."},{"t":"ol","i":["Avalie o item da ectoscopia que possa justificar a síndrome anêmica do paciente.","Avalie se existe &quot;inchaço&quot; nos membros inferiores do paciente.","Qual o termo semiológico para fezes com &quot;coloração de borra de café&quot;?"]}],"instrucao":"Exame normal.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Identificou o item: coloração das mucosas","pts":1.0},{"item":"Examinou conjuntiva palpebral inferior e mucosa oral com boa luz","pts":1.5},{"item":"Classificou: normocoradas ou descoradas, em cruzes; citou palidez palmar ou do leito ungueal","pts":1.0},{"item":"Edema: inspeção comparativa das duas pernas","pts":0.5},{"item":"Compressão firme e sustentada contra a tíbia, o maléolo e o dorso do pé, dos dois lados; procurou a fóvea (cacifo)","pts":2.0},{"item":"Descreveu localização, intensidade em cruzes e mais duas características (consistência, elasticidade, temperatura, sensibilidade)","pts":1.5},{"item":"Melena","pts":1.5}],"notas":["Se perguntarem a ligação entre os achados: o anti-inflamatório lesa a mucosa gástrica, causa sangramento digestivo alto (melena), e a perda crônica de sangue leva à anemia."]},{"id":"C-3fig","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Slide com três figuras","tema":"","corpo":[{"t":"p","h":"<strong>Tarefa.</strong> Nomeie o que é encontrado em cada figura."},{"t":"ol","i":["Região acima do lábio superior com uma lesão elevada, sólida, menor que 1 cm.","Antebraço com várias lesões elevadas, menores que 1 cm, de conteúdo líquido.","Rosto com a pele e as escleras amareladas."]}],"instrucao":"","checklist":[{"item":"Pápula: formação sólida, circunscrita, de até 1 cm.","pts":3.5},{"item":"Vesículas: coleções líquidas de até 1 cm (pústulas, se o conteúdo for purulento).","pts":3.5},{"item":"Icterícia: coloração amarelada da pele e das escleras por acúmulo de bilirrubina.","pts":3.0}],"notas":[],"img":"img/c_3fig.jpg"},{"id":"C-14","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 14","tema":"","corpo":[{"t":"p","h":"<strong>Cenário.</strong> Paciente do sexo feminino, 24 anos, com hipotireoidismo, procura atendimento por febre de 38 graus há 7 dias, fadiga, mialgia e aparecimento de &quot;caroços&quot; dolorosos no pescoço. Figura: dorso das mãos e punhos com manchas brancas de limites nítidos."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize a palpação dos principais linfonodos cervicais anteriores e posteriores, descrevendo os prováveis achados encontrados.","Descreva a alteração da figura.","Faça a palpação de tireoide."]}],"instrucao":"Diga que dói quando palparem os lados do pescoço.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Linfonodos cervicais anteriores e posteriores com técnica correta, dos dois lados","pts":2.0},{"item":"Prováveis achados: aumentados (maiores que 1 cm), dolorosos, móveis, consistência elástica ou amolecida, individualizados, com ou sem calor e rubor","pts":2.0},{"item":"Figura: manchas acrômicas, de limites nítidos, sem relevo, no dorso das mãos e punhos","pts":1.5},{"item":"Nomeou vitiligo","pts":0.5},{"item":"Tireoide: inspeção e palpação de istmo e lobos, com deglutição","pts":2.0},{"item":"Descreveu as características da glândula","pts":1.0}],"notas":["Se perguntarem: linfonodos dolorosos com febre sugerem mecanismo infeccioso; vitiligo e hipotireoidismo por tireoidite de Hashimoto têm mecanismo autoimune."],"img":"img/c_14.jpg"},{"id":"C-15","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 15","tema":"","corpo":[{"t":"p","h":"<strong>Cenário.</strong> Paciente de 76 anos, sexo feminino, apresenta fraqueza progressiva em membros inferiores há 10 dias. Relata que há aproximadamente 3 semanas recebeu vacinação contra influenza. Inicialmente apresentou formigamento nos pés, evoluindo para dificuldade para caminhar e levantar-se da cadeira. Nega alterações cognitivas. Queixa-se também de dor e deformidades nas mãos há vários anos. Figura: dorso das duas mãos, com aumento de volume nodular nas articulações dos dedos."},{"t":"p","h":"<strong>Tarefas.</strong> Realize o exame físico direcionado e, ao final, informe ao examinador:"},{"t":"ol","i":["Letra A: teste tônus, reflexo patelar e força de membros inferiores com o paciente deitado. Fale os achados que você deveria encontrar.","Letra B: qual o diagnóstico sindrômico?","Letra C: baseado na imagem, descreva as alterações articulares visualizadas."]}],"instrucao":"Deitado, pernas soltas e moles. Faça pouca força com as pernas: levante-as da maca, mas ceda quando o examinador resistir.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Tônus dos membros inferiores: movimentos passivos e balanço, dos dois lados","pts":1.0},{"item":"Achado esperado: hipotonia","pts":1.0},{"item":"Reflexo patelar deitado, joelhos semifletidos sustentados, dos dois lados","pts":1.0},{"item":"Achado esperado: hiporreflexia ou arreflexia","pts":1.0},{"item":"Força: distal para proximal, contra a gravidade e contra resistência, dos dois lados","pts":1.0},{"item":"Achado esperado: paraparesia simétrica; graduou e justificou (III ou IV)","pts":1.0},{"item":"Diagnóstico sindrômico: síndrome do segundo neurônio motor","pts":1.5},{"item":"Figura: nódulos nas interfalângicas distais (Heberden) e proximais (Bouchard), bilaterais","pts":1.5}],"notas":["Se perguntarem: suspeita de Guillain-Barré após vacinação (mecanismo autoimune/inflamatório); mãos com osteoartrite (mecanismo degenerativo)."],"img":"img/c_15.jpg"},{"id":"C-17","sim":"C","origem":"Slides fotografados da disciplina","titulo":"Estação 17","tema":"","corpo":[{"t":"p","h":"<strong>Cenário.</strong> Homem, 35 anos, está no pronto-socorro com queixa de fraqueza nas pernas que piorou rapidamente nas últimas 48 horas. A fraqueza começou nos pés há 2 dias e subiu para os joelhos e coxas bilateralmente. Agora sente dificuldade em levantar-se e andar. Sente formigamento (parestesia) nas mãos e pés, que é mais intenso que a fraqueza. Teve um quadro de diarreia (gastroenterite) há cerca de 4 semanas, que durou 3 dias. Negou febre."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Teste o tônus dos membros inferiores. O que você esperaria encontrar?","Teste o reflexo patelar e o cutâneo-plantar do paciente. O que você esperaria encontrar?","Qual o diagnóstico sindrômico?","Qual o mecanismo de lesão mais provável?"]}],"instrucao":"Igual à estação 15.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Tônus dos membros inferiores com técnica correta, dos dois lados","pts":1.5},{"item":"Esperado: hipotonia","pts":1.0},{"item":"Reflexo patelar com técnica correta, dos dois lados","pts":1.0},{"item":"Reflexo cutâneo-plantar: estímulo pela borda lateral da planta, do calcanhar para os dedos, dos dois lados","pts":1.0},{"item":"Esperado: patelar diminuído ou abolido; cutâneo-plantar em flexão ou sem resposta, sem sinal de Babinski","pts":1.5},{"item":"Diagnóstico sindrômico: síndrome do segundo neurônio motor","pts":1.5},{"item":"Mecanismo: autoimune/inflamatório, com a diarreia como gatilho; não é infeccioso","pts":1.5}],"notas":[]},{"id":"D1","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D1: manchas brancas, dor de garganta e caroços no pescoço","tema":"linfonodos, tireoide e vitiligo","corpo":[{"t":"p","h":"<strong>Caso.</strong> Paciente do sexo feminino, 28 anos, com manchas brancas nas mãos e no rosto que surgiram há 2 anos e aumentaram progressivamente, procura a Unidade Básica de Saúde por dor de garganta e febre baixa há 5 dias, associadas ao aparecimento de &quot;caroços&quot; dolorosos no pescoço. Refere ainda cansaço, sensação de frio e ganho de peso nos últimos meses. A mãe tem hipotireoidismo. A figura mostra mãos com manchas brancas."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize a palpação dos linfonodos cervicais anteriores e posteriores e descreva o aspecto esperado dos linfonodos.","Realize a palpação da tireoide e descreva o aspecto esperado da glândula.","Analise as manchas da figura e descreva suas características."]}],"instrucao":"Exame normal. Engula quando pedirem.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Linfonodos cervicais anteriores e posteriores: polpas digitais, movimentos circulares, cabeça inclinada para o lado examinado, dos dois lados","pts":2.0},{"item":"Aspecto esperado dos linfonodos: aumentados, dolorosos, móveis, fibroelásticos, não coalescentes, pele normal ou quente (padrão inflamatório)","pts":1.5},{"item":"Tireoide: inspeção com deglutição; palpação do istmo e dos dois lobos, pedindo deglutição","pts":2.0},{"item":"Aspecto esperado da tireoide: aumento difuso, consistência firme, superfície irregular, indolor, móvel (tireoidite de Hashimoto)","pts":1.5},{"item":"Manchas: brancas (acrômicas), bem delimitadas, planas, sem descamação, no dorso das mãos e no rosto","pts":1.5},{"item":"Nomeou vitiligo e relacionou com doença autoimune da tireoide","pts":0.5}],"notas":["Se o avaliador perguntar: os linfonodos dolorosos com dor de garganta e febre há 5 dias são reacionais; cansaço, frio, ganho de peso e mãe com hipotireoidismo sugerem hipotireoidismo autoimune, que se associa ao vitiligo."],"img":"img/d1.jpg","fig":"dorso das mãos com manchas brancas de limites nítidos."},{"id":"D2","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D2: dificuldade para andar e fraqueza progressiva nas pernas","tema":"fraqueza ascendente","corpo":[{"t":"p","h":"<strong>Caso.</strong> Paciente do sexo feminino, 41 anos, previamente hígida, procura o pronto-atendimento com queixa de formigamento nos pés que começou há 5 dias e foi seguido de fraqueza nas pernas, que piorou de forma progressiva e passou a atingir também as coxas, com dificuldade para levantar da cadeira e andar. Refere que, há cerca de 2 semanas, teve um quadro de infecção respiratória que durou 4 dias. Nega febre atual, trauma, dor lombar intensa e alteração urinária."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize a avaliação do tônus e da força muscular dos membros inferiores e descreva os achados esperados, informando a graduação da força.","Realize a avaliação dos reflexos dos membros inferiores e informe a graduação esperada.","Identifique o diagnóstico sindrômico mais provável."]}],"instrucao":"Deixe as pernas moles. Faça pouca força contra a resistência, igual dos dois lados e pior nos pés.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Tônus: inspeção, palpação das massas musculares e movimentação passiva de quadril, joelho e tornozelo, dos dois lados","pts":1.5},{"item":"Achado esperado do tônus: hipotonia","pts":1.0},{"item":"Força: manobra deficitária (Mingazzini ou Barré) e força contra resistência por segmento, comparando os lados","pts":1.5},{"item":"Informou a graduação de 0 a 5 (por exemplo, grau 3 distal e grau 4 proximal, simétrica)","pts":1.0},{"item":"Reflexos patelar e aquileu com técnica correta, dos dois lados; cutâneo-plantar","pts":1.5},{"item":"Graduação esperada dos reflexos: abolidos (0) ou hipoativos (+)","pts":1.0},{"item":"Síndrome do segundo neurônio motor; polirradiculoneurite aguda (Guillain-Barré)","pts":1.5}],"notas":["Se o avaliador perguntar: fraqueza ascendente e simétrica, com parestesias, dias depois de uma infecção, sem nível sensitivo e sem alteração urinária; mecanismo autoimune."]},{"id":"D3","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D3: dor, inchaço e rigidez nas mãos","tema":"artrite reumatoide","corpo":[{"t":"p","h":"<strong>Caso.</strong> Paciente do sexo feminino, 52 anos, procura o ambulatório com queixa de dor e inchaço nas articulações das mãos há 1 ano, de início insidioso e acometimento simétrico. Refere rigidez matinal que dura mais de 1 hora e dificuldade para abotoar a roupa e abrir potes. Refere também cansaço e dor nos pés. Nega trauma. A figura mostra as duas mãos com deformidades."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Cite os sinais cardinais da artrite.","Realize o exame das mãos e descreva os achados esperados.","Analise a figura e descreva as alterações características da artrite reumatoide."]}],"instrucao":"Diga que dói quando apertarem sua mão de lado a lado.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Sinais cardinais: dor, calor, rubor, tumor (edema) e limitação funcional","pts":2.0},{"item":"Inspeção estática e dinâmica das mãos e dos punhos (abrir e fechar, pinça, flexão e extensão do punho)","pts":1.5},{"item":"Palpação de punhos, metacarpofalângicas e interfalângicas; squeeze","pts":1.5},{"item":"Achados esperados: aumento de volume simétrico, calor e dor em punhos, metacarpofalângicas e interfalângicas proximais; squeeze positivo; limitação de movimento","pts":1.5},{"item":"Figura: aumento de volume e subluxação das metacarpofalângicas, desvio ulnar dos dedos, deformidades digitais, acometimento bilateral e simétrico","pts":2.0},{"item":"Disse que as interfalângicas distais são poupadas ou que o padrão é inflamatório","pts":0.5}],"notas":["Se o avaliador perguntar: rigidez matinal de mais de 1 hora, simetria e acometimento de pequenas articulações indicam mecanismo inflamatório autoimune."],"img":"img/d3.jpg","fig":"as duas mãos, com aumento de volume das articulações na base dos dedos e dedos desviados para o lado do dedo mínimo, dos dois lados."},{"id":"D4","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D4: lesões de pele em paciente anticoagulada","tema":"eritema, petéquias e placa","corpo":[{"t":"p","h":"<strong>Caso.</strong> Paciente de 22 anos com cardiopatia valvar congênita necessitou realizar uma cirurgia de troca valvar para uma válvula metálica, estando em uso de anticoagulante (varfarina). Sua mãe tem hipotireoidismo primário autoimune. Ela apresenta diversas lesões de pele e por isso procurou o dermatologista. O slide mostra as lesões A, B e C."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Descreva as lesões observadas nas figuras.","Como distinguir a lesão A e B?"]}],"instrucao":"","checklist":[{"item":"Moldura (descrição organizada: tipo de lesão, cor, relevo, limites, distribuição)","pts":1.0},{"item":"Lesão A: mancha eritematosa extensa e plana (eritema)","pts":2.0},{"item":"Lesão B: petéquias, manchas hemorrágicas puntiformes (púrpura)","pts":2.0},{"item":"Lesão C: placa eritematodescamativa bem delimitada; psoríase","pts":2.0},{"item":"Distinção entre A e B: digitopressão ou vitropressão; o eritema desaparece e a púrpura não","pts":2.0},{"item":"Relacionou as petéquias ao uso de anticoagulante","pts":1.0}],"notas":[],"img":"img/d4.jpg","fig":"A, área extensa de pele avermelhada e plana; B, vários pontos vermelho-arroxeados, muito pequenos e planos; C, lesão elevada, avermelhada, de limites nítidos, coberta por escamas esbranquiçadas."},{"id":"D5","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D5: dores nas mãos e no punho","tema":"mãos, punho e túnel do carpo","corpo":[{"t":"p","h":"<strong>Caso.</strong> Paciente, sexo feminino, 38 anos, procura atendimento por dores nas mãos e no punho."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Execute o exame das mãos e punho.","Como você pode diferenciar artrite e osteoartrose com base na anamnese e exame físico?","Faça os sinais de Tinel e Phalen e indique a condição em que se encontram alterados."]}],"instrucao":"No Phalen, depois de uns 30 segundos, diga que formigam o polegar, o indicador e o dedo médio.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção estática: pele, volume, deformidades, atrofia da eminência tenar, simetria","pts":1.0},{"item":"Inspeção dinâmica: flexão, extensão e desvios do punho, pronação e supinação, abrir e fechar a mão, oposição do polegar","pts":1.0},{"item":"Palpação de punho, metacarpofalângicas e interfalângicas; squeeze","pts":1.5},{"item":"Artrite contra osteoartrose pela anamnese: rigidez matinal longa ou curta e ritmo da dor (repouso ou movimento)","pts":1.5},{"item":"Artrite contra osteoartrose pelo exame: articulações acometidas, sinais inflamatórios ou nódulos duros com crepitação","pts":1.5},{"item":"Tinel (percussão do nervo mediano no punho) e Phalen (flexão máxima dos punhos por 30 a 60 segundos) com técnica correta","pts":1.5},{"item":"Condição: síndrome do túnel do carpo, compressão do nervo mediano","pts":1.0}],"notas":[]},{"id":"D6","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D6: traumatismo no nível de L1","tema":"choque medular","corpo":[{"t":"p","h":"<strong>Caso.</strong> 25 anos, sexo feminino, sofre um acidente de trânsito com traumatismo a nível de L1 detectado durante a avaliação inicial. Considerando a fase aguda do trauma:"},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Execute o exame do tônus muscular dos membros inferiores e indique a alteração esperada.","Execute o exame dos reflexos dos membros inferiores e indique a alteração esperada.","Qual a síndrome neurológica do caso?"]}],"instrucao":"Deixe as pernas completamente moles e não ajude nos movimentos.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Tônus dos membros inferiores: inspeção, palpação e movimentação passiva, dos dois lados","pts":2.0},{"item":"Alteração esperada do tônus: hipotonia (flacidez)","pts":1.5},{"item":"Reflexos patelar, aquileu e cutâneo-plantar com técnica correta, dos dois lados","pts":2.0},{"item":"Alteração esperada dos reflexos: arreflexia","pts":1.5},{"item":"Síndrome medular (primeiro neurônio motor) em fase de choque medular","pts":1.5},{"item":"Disse que depois surgem espasticidade, hiper-reflexia e sinal de Babinski","pts":0.5}],"notas":[]},{"id":"D7","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D7: quatro figuras de pele","tema":"quatro lesões de pele","corpo":[{"t":"p","h":"<strong>Caso.</strong> O slide mostra quatro figuras de lesões de pele, numeradas de 1 a 4."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Identifique os principais achados de ectoscopia nos seguintes casos e o mecanismo de base."]}],"instrucao":"","checklist":[{"item":"Moldura (descrição organizada: cor, relevo, conteúdo, limites, distribuição)","pts":2.0},{"item":"Figura 1: crostas; ressecamento de serosidade, pus ou sangue","pts":2.0},{"item":"Figura 2: pústulas; coleção de pus","pts":2.0},{"item":"Figura 3: vesículas ou erosões agrupadas sobre base eritematosa; coleção líquida que se rompe","pts":2.0},{"item":"Figura 4: bolha e vesículas; coleção líquida, diferenciadas pelo tamanho","pts":2.0}],"notas":[],"img":"img/d7.jpg","fig":"1, lesões cobertas por material ressecado, amarelado ou acastanhado; 2, pequenas elevações de conteúdo amarelado; 3, pequenas lesões de conteúdo líquido, agrupadas sobre pele avermelhada, algumas rompidas; 4, uma elevação grande de conteúdo líquido ao lado de outras menores."},{"id":"D8","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D8: quatro figuras de ectoscopia geral","tema":"ectoscopia geral","corpo":[{"t":"p","h":"<strong>Caso.</strong> O slide mostra quatro figuras numeradas: um homem sem camisa, um abdome e um rosto, duas conjuntivas e uma mão."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Identifique os principais achados de ectoscopia nos seguintes casos e o mecanismo de base."]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Figura 1: circulação colateral na parede abdominal e ginecomastia","pts":1.5},{"item":"Mecanismo da figura 1: hipertensão portal e excesso relativo de estrogênios (cirrose)","pts":1.0},{"item":"Figura 2: ascite e icterícia","pts":1.5},{"item":"Mecanismo da figura 2: hipertensão portal com hipoalbuminemia; aumento da bilirrubina","pts":1.0},{"item":"Figura 3: palidez da mucosa conjuntival","pts":1.0},{"item":"Mecanismo da figura 3: redução da hemoglobina (anemia)","pts":1.0},{"item":"Figura 4: cianose de extremidades","pts":1.0},{"item":"Mecanismo da figura 4: aumento da hemoglobina reduzida no sangue capilar","pts":1.0}],"notas":[],"img":"img/d8.jpg","fig":"1, homem com veias dilatadas visíveis na parede do abdome e aumento das mamas; 2, abdome globoso e distendido e rosto com pele e escleras amareladas; 3, conjuntivas palpebrais descoradas; 4, mão com as pontas dos dedos azuladas."},{"id":"D9","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D9: perda de força há 50 minutos","tema":"síndrome piramidal aguda","corpo":[{"t":"p","h":"<strong>Caso.</strong> L.T.M., 56 anos, apresentou perda de força e dificuldade para deambular, de início há 50 min. Tem diabetes e hipertensão prévias."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Execute o exame de força muscular dos membros superiores. Quais os achados esperados?","Execute o exame dos reflexos bicipital e tricipital. Quais os achados esperados?","Qual a síndrome neurológica do caso?"]}],"instrucao":"Faça menos força com o braço e a mão direitos. Na prova dos braços estendidos, deixe o direito cair devagar.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Prova dos braços estendidos","pts":1.5},{"item":"Força contra resistência por segmento (ombro, cotovelo, punho, preensão), comparando os lados","pts":1.5},{"item":"Graduou de 0 a 5 e disse o achado esperado: fraqueza de um lado (hemiparesia)","pts":1.5},{"item":"Reflexos bicipital e tricipital com técnica correta, dos dois lados","pts":2.0},{"item":"Achado esperado: hiper-reflexia no lado parético (ou reflexos normais ou diminuídos, por ser fase aguda)","pts":1.0},{"item":"Síndrome piramidal (primeiro neurônio motor)","pts":1.5}],"notas":["Se o avaliador perguntar: déficit súbito em paciente com diabetes e hipertensão indica mecanismo vascular (acidente vascular cerebral)."]},{"id":"D10","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D10: idoso com quedas e tremor","tema":"síndrome parkinsoniana","corpo":[{"t":"p","h":"<strong>Caso.</strong> Idoso de 65 anos, sexo masculino, apresentando quedas frequentes de própria altura, tremores finos das mãos em repouso, de grande amplitude, e lentificação do movimento. Tem tido dificuldade para se alimentar e a esposa nota que não reconhece as pessoas como antigamente e demora para responder a perguntas simples."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Execute o exame do tônus muscular. Dê o diagnóstico da alteração.","Execute o exame de equilíbrio estático e dinâmico. Dê o diagnóstico da alteração.","Qual a síndrome neurológica do caso?"]}],"instrucao":"Deixe os braços um pouco duros, cedendo aos trancos. Ande com passos curtos, inclinado para a frente e sem balançar os braços. Mantenha um tremor das mãos em repouso.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Tônus: movimentação passiva de punho e cotovelo, dos dois lados","pts":1.5},{"item":"Diagnóstico do tônus: hipertonia plástica, com roda denteada","pts":1.5},{"item":"Equilíbrio estático: em pé, pés juntos, olhos abertos e depois fechados, protegendo o paciente","pts":1.5},{"item":"Equilíbrio dinâmico: marcha de ida e volta, com giro","pts":1.0},{"item":"Diagnóstico: instabilidade postural e marcha parkinsoniana (em bloco, passos curtos, sem balanço dos braços)","pts":1.5},{"item":"Síndrome parkinsoniana (extrapiramidal)","pts":1.5},{"item":"Citou tremor de repouso e bradicinesia como componentes","pts":0.5}],"notas":[]},{"id":"D11","sim":"D","origem":"Estações digitadas e slides de 20/11","titulo":"Estação D11: dor cervical anterior e submandibular","tema":"tireoide dolorosa e linfonodos reacionais","corpo":[{"t":"p","h":"<strong>Caso.</strong> Paciente de 32 anos procura seu atendimento por uma dor na região cervical anterior e submandibular há 5 dias, febre nos primeiros 2 dias, tosse seca e dor de garganta e no ouvido."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Faça o exame da tireoide e descreva o que você observou.","Faça o exame dos linfonodos e descreva o que você observou."]}],"instrucao":"Diga que dói quando palparem a frente do pescoço e quando engolir.","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção do pescoço com deglutição","pts":1.0},{"item":"Palpação da tireoide: istmo e os dois lobos, com deglutição","pts":2.0},{"item":"Descreveu volume, consistência, superfície, mobilidade, sensibilidade e nódulos; no caso, glândula aumentada e dolorosa","pts":1.5},{"item":"Linfonodos: cadeias da cabeça e do pescoço em sequência, dos dois lados","pts":2.0},{"item":"Descreveu tamanho, consistência, mobilidade, sensibilidade, coalescência e pele; no caso, padrão reacional","pts":1.5},{"item":"Hipótese: tireoidite subaguda, ou infecção de vias aéreas com linfonodos reacionais","pts":1.0}],"notas":[]},{"id":"E1","sim":"E","origem":"Simulado 2026/2, checklist oficial","titulo":"Estação E1: fraqueza no lado esquerdo do corpo e disartria","tema":"síndrome do primeiro neurônio motor","corpo":[{"t":"p","h":"<strong>Caso.</strong> Paciente de 64 anos, hipertenso, sedentário e tabagista, relata quadro de fraqueza no lado esquerdo do corpo, disartria e desvio de rima labial para a direita de início súbito há 6 meses."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize a avaliação do tônus muscular dos membros superiores e cite qual é o achado esperado neste paciente.","Realize a manobra do reflexo bicipital e patelar, e descreva os achados esperados.","Identifique o diagnóstico sindrômico mais provável."]}],"instrucao":"Deixe o braço esquerdo mais duro: resista no começo do movimento e ceda de repente.","checklist":[{"item":"Cumprimentar o paciente, apresentar-se pelo nome e demonstrar cordialidade","pts":1.0},{"item":"Tônus: com o paciente relaxado, palpar a musculatura ou fazer flexão e extensão passivas dos cotovelos e punhos, dos dois lados","pts":2.0},{"item":"Citar hipertonia elástica (espástica) à esquerda ou sinal do canivete à esquerda","pts":1.5},{"item":"Bicipital: antebraço relaxado em semiflexão, polegar sobre o tendão do bíceps na prega do cotovelo, percutir sobre o próprio dedo, dos dois lados","pts":1.5},{"item":"Patelar: sentado com as pernas pendentes, ou deitado com o joelho semifletido apoiado; percutir o tendão patelar dos dois lados","pts":1.5},{"item":"Descrever hiper-reflexia à esquerda em comparação com a direita, nos dois reflexos","pts":1.5},{"item":"Identificar a síndrome do primeiro neurônio motor (piramidal)","pts":1.0}],"notas":["Observações do gabarito: quadro típico de síndrome do primeiro neurônio motor, com hemiparesia à esquerda, desvio de rima para a direita, disartria, sinal do canivete e hiper-reflexia do hemicorpo acometido, causado por AVC, que é a etiologia provável pelos fatores de risco. Como o início foi há 6 meses, espera-se nessa fase a liberação piramidal, com os sinais de espasticidade estabelecidos."]},{"id":"E2","sim":"E","origem":"Simulado 2026/2, checklist oficial","titulo":"Estação E2: dor em queimação na pele, lesões e caroços no pescoço","tema":"herpes-zóster, linfonodos e trigêmeo","corpo":[{"t":"p","h":"<strong>Caso.</strong> Paciente de 62 anos procura o pronto-atendimento queixando-se de dor intensa em queimação na pele há 3 dias, acompanhada do surgimento das lesões no mesmo local. Relata também ter notado pequenos &quot;caroços&quot; no pescoço nos últimos dias. Em seus antecedentes patológicos, refere histórico de varicela na infância. O caso é acompanhado de imagens da lesão."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Descreva a lesão elementar apresentada na imagem.","Realize a palpação dos linfonodos da cadeia cervical anterior e descreva os achados esperados em um quadro de infecção viral.","Realize a avaliação da porção motora do nervo trigêmeo (NC V)."]}],"instrucao":"Exame normal. Cerre os dentes com força quando pedirem.","checklist":[{"item":"Cumprimentar o paciente, apresentar-se pelo nome e demonstrar cordialidade","pts":1.0},{"item":"Lesão elementar: vesículas agrupadas sobre base eritematosa, em faixa de um dermátomo, unilateral, que não cruza a linha média","pts":3.0},{"item":"Linfonodos cervicais anteriores: atrás do paciente, cabeça levemente inclinada, palpar os dois lados com o polegar apoiado no esternocleidomastóideo, movendo os tecidos moles contra o músculo","pts":2.0},{"item":"Achados prováveis: linfonodos discretamente aumentados, móveis, fibroelásticos, não aderidos aos planos profundos, indolores ou pouco dolorosos","pts":2.0},{"item":"Porção motora do trigêmeo: pedir que cerre os dentes com força e palpar masseter e temporal dos dois lados","pts":2.0}],"notas":["Observações do gabarito: o caso é típico de herpes-zóster no dermátomo de V1, em paciente com mais de 60 anos e história de varicela. O vírus fica latente no gânglio sensitivo e, na reativação, migra pelo nervo até a pele. A dor em queimação precede ou acompanha as lesões, que evoluem de máculo-pápulas eritematosas para vesículas, pústulas, úlceras e crostas, com cicatrização em 2 a 4 semanas. A adenopatia cervical reativa é esperada. Alterações da porção motora do trigêmeo são raras nesse caso. Na avaliação motora também se aceita pedir a abertura da boca, observar desvio da mandíbula para o lado afetado e testar a lateralização contra resistência."],"img":"img/e2.jpg","fig":"lesões pequenas, de conteúdo líquido, agrupadas sobre pele avermelhada, dispostas em faixa na testa e ao redor do olho de um só lado, sem ultrapassar a linha média."},{"id":"F1","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F1: AVC há 6 semanas","tema":"hemiparesia espástica","corpo":[{"t":"p","h":"<strong>Caso.</strong> Homem, 65 anos, com história de AVC isquêmico à direita há 6 semanas."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Teste a motricidade dos membros superiores e inferiores.","Quais são os achados esperados?","Qual a hipótese diagnóstica?"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Força: manobras deficitárias (braços estendidos, Mingazzini) e força por segmento, comparando os lados","pts":2.0},{"item":"Tônus e reflexos profundos dos quatro membros; cutâneo-plantar","pts":2.0},{"item":"Achados: fraqueza e hiper-reflexia no hemicorpo esquerdo, sinal de Babinski à esquerda, hipertonia com sinal do canivete","pts":3.0},{"item":"Marcha hemiplégica e perda sensitiva leve","pts":1.0},{"item":"Síndrome do primeiro neurônio motor; hemiparesia espástica pós-AVC","pts":1.0}],"notas":[]},{"id":"F2","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F2: instabilidade ao andar e tremor de intenção","tema":"síndrome cerebelar","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 47 anos, alcoolista crônica, com queixa de instabilidade ao andar e tremor de intenção."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie a coordenação.","Quais são os achados esperados?","Qual a hipótese diagnóstica?"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Índex-nariz e índex-índex, de olhos abertos e fechados","pts":2.0},{"item":"Calcanhar-joelho","pts":1.5},{"item":"Movimentos alternados rápidos (diadococinesia)","pts":1.5},{"item":"Marcha e fala","pts":1.0},{"item":"Achados: ataxia, dismetria, disartria, disdiadococinesia","pts":2.0},{"item":"Síndrome cerebelar","pts":1.0}],"notas":[]},{"id":"F3","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F3: fraqueza progressiva após quadro gripal","tema":"Guillain-Barré","corpo":[{"t":"p","h":"<strong>Caso.</strong> Jovem, 25 anos, após quadro gripal, com queixa de fraqueza progressiva em membros inferiores."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie força muscular, reflexos profundos e sensibilidade.","Quais são os achados esperados?","Qual a principal hipótese diagnóstica?"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Força dos membros inferiores, comparando os lados, com graduação","pts":2.0},{"item":"Reflexos patelar e aquileu, dos dois lados","pts":2.0},{"item":"Sensibilidade superficial e profunda, do distal para o proximal","pts":2.0},{"item":"Achados: fraqueza simétrica, hiporreflexia ou arreflexia, redução da sensibilidade","pts":2.0},{"item":"Síndrome de Guillain-Barré","pts":1.0}],"notas":[]},{"id":"F4","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F4: dormência em mãos e pés","tema":"neuropatia periférica","corpo":[{"t":"p","h":"<strong>Caso.</strong> Homem, 55 anos, diabético, com queixa de dormência e formigamento em mãos e pés."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie a sensibilidade superficial e profunda.","Quais são os achados esperados?","Qual a principal hipótese diagnóstica?"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Explicou o exame, pediu olhos fechados e comparou os lados e o distal com o proximal","pts":1.5},{"item":"Superficial: tátil com algodão e dolorosa com objeto pontiagudo","pts":2.0},{"item":"Profunda: vibratória com diapasão nas saliências ósseas e cinético-postural","pts":2.0},{"item":"Achados: redução da sensibilidade vibratória e tátil nas extremidades, em luva e bota","pts":2.5},{"item":"Neuropatia periférica (para os monitores, síndrome do segundo neurônio motor)","pts":1.0}],"notas":[]},{"id":"F5","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F5: desequilíbrio que piora no escuro","tema":"síndrome do funículo posterior","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 72 anos, com histórico de etilismo crônico e alimentação precária, procura atendimento por desequilíbrio progressivo ao caminhar, principalmente no escuro, e formigamento nas pernas."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Faça o teste do equilíbrio e avalie a sensibilidade.","Quais são os achados esperados?","Qual a principal hipótese diagnóstica?"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Romberg: pés juntos, olhos abertos e depois fechados, protegendo o paciente","pts":2.0},{"item":"Marcha","pts":1.0},{"item":"Sensibilidade vibratória e cinético-postural nos pés","pts":2.0},{"item":"Achados: Romberg positivo, marcha tabética, perda da sensibilidade vibratória e proprioceptiva nos pés","pts":3.0},{"item":"Síndrome do funículo posterior","pts":1.0}],"notas":[]},{"id":"F6","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F6: dor lombar irradiada para a perna","tema":"lombalgia com ciatalgia","corpo":[{"t":"p","h":"<strong>Caso.</strong> Homem, 40 anos, trabalhador rural, com dor lombar irradiando para o membro inferior direito."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie a coluna lombar e o nervo ciático.","Quais são os achados esperados?","Cite uma hipótese diagnóstica."]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção estática e dinâmica da coluna lombar","pts":1.5},{"item":"Palpação das apófises espinhosas e da musculatura paravertebral","pts":1.5},{"item":"Lasègue dos dois lados, dizendo o ângulo e o trajeto da dor","pts":2.0},{"item":"Força (andar nos calcanhares e na ponta dos pés) e reflexos","pts":1.0},{"item":"Achados: dor à palpação lombar, sinal de Lasègue, força preservada","pts":2.0},{"item":"Hipótese: hérnia de disco","pts":1.0}],"notas":[]},{"id":"F7","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F7: rigidez matinal e deformidade das mãos","tema":"artrite reumatoide","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 60 anos, com rigidez matinal e deformidade das mãos."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Avalie as articulações interfalângicas e metacarpofalângicas.","Quais são os achados esperados?"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção das mãos: volume, deformidades, simetria","pts":2.0},{"item":"Palpação das metacarpofalângicas e interfalângicas; squeeze","pts":2.0},{"item":"Movimentos: abrir e fechar a mão, pinça","pts":1.0},{"item":"Achados: deformidade, dor, edema articular, espessamento articular","pts":3.0},{"item":"Artrite reumatoide","pts":1.0}],"notas":[]},{"id":"F8","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F8: aumento progressivo do pescoço","tema":"bócio","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 39 anos, relata &quot;aumento no pescoço&quot; progressivo nos últimos meses, com sensação de pressão na região cervical anterior, principalmente ao engolir, palpitações e perda de peso involuntária. O caso é acompanhado de uma imagem do pescoço."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize a palpação da glândula tireoide.","Nomeie o achado clínico presente na imagem."]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Inspeção do pescoço com deglutição","pts":1.5},{"item":"Palpação do istmo e dos dois lobos, com deglutição","pts":2.5},{"item":"Descreveu volume, consistência, superfície, mobilidade, sensibilidade e nódulos","pts":2.0},{"item":"Nomeou o achado da imagem: bócio","pts":2.0},{"item":"Relacionou palpitações e perda de peso a hipertireoidismo","pts":1.0}],"notas":["O slide dos monitores não traz a resposta deste caso; bócio é a leitura de quem montou este treino."],"img":"img/f8.jpg","fig":"pescoço com aumento de volume difuso na região anterior."},{"id":"F9","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F9: seguimento de câncer de mama","tema":"linfonodos axilares","corpo":[{"t":"p","h":"<strong>Caso.</strong> Mulher, 55 anos, diagnosticada com carcinoma ductal invasivo em mama esquerda, sem queixa local, em seguimento oncológico."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize a palpação dos linfonodos axilares esquerdos.","Quais os achados esperados?","Qual a hipótese diagnóstica?"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Posição: de frente para a paciente, sustentando o braço dela para relaxar a axila","pts":2.0},{"item":"Palpação das paredes da axila, deslizando a pele contra o gradil costal","pts":2.5},{"item":"Achados: adenomegalia axilar de consistência endurecida, pouco móvel, indolor, sem sinais inflamatórios na pele","pts":3.5},{"item":"Linfadenopatia axilar metastática associada ao câncer de mama","pts":1.0}],"notas":[]},{"id":"F10","sim":"F","origem":"Revisão dos monitores","titulo":"Estação F10: dor de garganta e ínguas no pescoço","tema":"linfadenopatia reacional","corpo":[{"t":"p","h":"<strong>Caso.</strong> Adolescente, 17 anos, sexo masculino, estudante, com dor de garganta, febre baixa e ínguas doloridas no pescoço há 3 dias."},{"t":"p","h":"<strong>Tarefas</strong>"},{"t":"ol","i":["Realize a palpação dos linfonodos cervicais anteriores e submandibulares.","Quais os achados esperados?","Qual a hipótese diagnóstica?"]}],"instrucao":"","checklist":[{"item":"Moldura","pts":1.0},{"item":"Palpação das cadeias submandibular e submentoniana","pts":2.0},{"item":"Palpação das cadeias cervicais anteriores, dos dois lados","pts":2.0},{"item":"Achados: linfonodos aumentados dos dois lados, de consistência amolecida e fibroelástica, dolorosos, móveis e sem aderência aos planos profundos","pts":4.0},{"item":"Linfadenopatia reacional secundária a faringoamigdalite","pts":1.0}],"notas":[]}];
